
/**
 * Selects a random rectangle from the visualization.
 * @returns {Object} The selected rectangle's data
 */
export function selectRandomRectangle() {
    const rectangles = d3.selectAll(".bars .rect3").nodes();

    if (rectangles.length === 0) {
        return;
    }

    const filteredRectangles = rectangles.filter(rect => {
        const rectData = d3.select(rect).datum();
        return (rectData[1] - rectData[0]) > 0.1;
    });

    const randomIndex = Math.floor(Math.random() * filteredRectangles.length);
    const randomRect = filteredRectangles[randomIndex];


    randomRect.setAttribute("stroke", "black");
    randomRect.setAttribute("stroke-width", "2");
    randomRect.setAttribute("stroke-dasharray", "4,2");
    randomRect.parentNode.appendChild(randomRect);
    randomRect.parentNode.parentNode.appendChild(randomRect.parentNode);

    const rectData = d3.select(randomRect).datum();

    return {
        category: rectData.category,
        interval: rectData.data.interval,
        proportion: `${((rectData[1] - rectData[0]) * 100).toFixed(2)}%`
    }
}

/**
 * Generates an example phrase for the visualization based on the selected rectangle's data.
 * @param {Object} dataExample - The selected rectangle's data
 * @param {Function} colorScale - The color scale for the visualization
 * @param {string} metric - The selected metric
 * @returns {string} The generated example phrase
 */
export function examplePhrase(dataExample, colorScale, metric) {

    const partsOfInterval = dataExample.interval.replace("[", "").replace("]", "").split(",");
    const startYear = partsOfInterval[0].trim();
    const endYear = partsOfInterval[1].trim();

    function categoryIsLenght(category) {
        const regex = /(\d+)-(\d+)/;
        const match = category.match(regex);
        if (match) {
            const num1 = match[1];
            const num2 = match[2];
            return [num1, num2]
        } else {
            return null;
        }
    }


    let categoryExplicit = dataExample.category;
    if (categoryIsLenght(dataExample.category)) {
        const [num1, num2] = categoryIsLenght(dataExample.category);
        categoryExplicit = `${num1} à ${num2}min`
    }



    let descriptionMarche = ""
    let metricSelected = ""
    if (metric === "box_office") {
        metricSelected = "Comme la métrique sélectionnée est le box-office :"
        descriptionMarche = `cela veut dire que la catégorie <strong style="color : ${colorScale(dataExample.category)}">${categoryExplicit}</strong> représentait <strong>${dataExample.proportion}</strong> du box-office réalisé entre <strong>${startYear}</strong> et <strong>${endYear}</strong>`
    }
    if (metric === "rating") {
        metricSelected = "Comme la métrique sélectionnée est la position dans le classement :"
        descriptionMarche = `cela veut dire que la catégorie <strong style="color : ${colorScale(dataExample.category)}">${categoryExplicit}</strong> représentait <strong>${dataExample.proportion}</strong> des films présents dans le classement IMDB entre <strong>${startYear}</strong> et <strong>${endYear}</strong>`
    }
    if (metric === "numNominations") {
        metricSelected = "Comme la métrique sélectionnée est le nombre de nominations :"
        descriptionMarche = `cela veut dire que que la catégorie <strong style="color : ${colorScale(dataExample.category)}">${categoryExplicit}</strong> représentait <strong>${dataExample.proportion}</strong> des nominations aux Oscars et Golden Globes entre <strong>${startYear}</strong> et <strong>${endYear}</strong>`
    }
    if (metric === "profit") {
        metricSelected = "Comme la métrique sélectionnée est le profit généré :"
        descriptionMarche = `cela veut dire que que la catégorie <strong style="color : ${colorScale(dataExample.category)}">${categoryExplicit}</strong> représentait <strong>${dataExample.proportion}</strong> du profit réalisé entre <strong>${startYear}</strong> et <strong>${endYear}</strong>`
    }

    const ExempleLecture = `
    <div class="exempleViz3">
        <strong style="text-decoration : underline">Exemple de Lecture</strong> : Entre <strong>${startYear}</strong> et <strong>${endYear}</strong>, la catégorie <strong style="color : ${colorScale(dataExample.category)}">${dataExample.category}</strong> représentait <strong>${dataExample.proportion}</strong> du marché. ${metricSelected} ${descriptionMarche}
    </div>`

    return ExempleLecture
}